<script lang="ts">
  import type {Database,DatabaseViewConfig,Page} from "@/features/notion-ui/variants/database/types"; import {dateProp,propValue} from "../../lib/view-core";
  let {db,view,rows,onOpenRow}= $props<{db:Database;view:DatabaseViewConfig;rows:Page[];onOpenRow?:(id:string)=>void}>(); let startProp=$derived(dateProp(db,view)),endProp=$derived(db.properties.find(p=>p.id===view.timelineEndProp)); let items=$derived(rows.flatMap(row=>{const s=startProp?propValue(row,startProp):null,e=endProp?propValue(row,endProp):null;const start=typeof s==="object"&&s&&!Array.isArray(s)?s.date:typeof s==="string"?s:null;const end=typeof e==="object"&&e&&!Array.isArray(e)?e.date:typeof e==="string"?e:(typeof s==="object"&&s&&!Array.isArray(s)?s.end:null);return start?[{row,start:Date.parse(start),end:Date.parse(end||start)}]:[]})); let min=$derived(Math.min(...items.map(i=>i.start),Date.now())),max=$derived(Math.max(...items.map(i=>i.end),min+86400000)); const left=(v:number)=>(v-min)/(max-min)*100;
</script>
<div class="space-y-1 p-3">{#if !startProp}<p class="rounded border p-4 text-xs text-muted-foreground">Configure a date property for Timeline.</p>{:else}{#each items as item (item.row.id)}<div class="grid grid-cols-[160px_1fr] items-center gap-2"><button class="truncate text-left text-xs font-medium" onclick={()=>onOpenRow?.(item.row.id)}>{item.row.title||"Untitled"}</button><div class="relative h-8 rounded bg-muted/30"><button class="absolute top-1 h-6 min-w-2 rounded bg-foreground/75" style={`left:${left(item.start)}%;width:${Math.max(2,left(item.end)-left(item.start)+2)}%`} onclick={()=>onOpenRow?.(item.row.id)} aria-label={item.row.title}></button></div></div>{/each}{/if}</div>
